shellCommands.command:
/bin/bash -lc "node --input-type=module <<'EOF'
import { readFile } from 'node:fs/promises'
const before = await readFile('/tmp/posts-before.html', 'utf8')
const actionName = before.match(/name=\"(\\"'$ACTION_ID_[''^"]+)"/)?.[1]
if (!actionName) throw new Error('"'Server Action form field was not rendered')
const form = new FormData()
form.set('title', 'Fresh cache test')
form.set('content', 'Visible immediately after creation')
form.set(actionName, '')
const submitted = await fetch('http://localhost:3001/', {
  method: 'POST',
  headers: { Origin: 'http://localhost:3001' },
  body: form,
  redirect: 'follow',
})
const actionHtml = await submitted.text()
const next = await fetch('http://localhost:3001/', { cache: 'no-store' })
const nextHtml = await next.text()
console.log(JSON.stringify({
  submitStatus: submitted.status,
  visibleInActionResponse: actionHtml.includes('Fresh cache test'),
  nextPageStatus: next.status,
  visibleOnNextPageLoad: nextHtml.includes('Fresh cache test'),
}))
if ("'!submitted.ok || !next.ok || !nextHtml.includes('"'Fresh cache test')) process.exitCode = 1
EOF"
